text:
Use `pg` pool. Config:

```js
import { Pool } from 'pg';

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Pool sizing
  max: 20,          // max connections (default 10)
  min: 2,           // keep alive when idle
  idleTimeoutMillis: 30_000,    // kill idle conn after 30s
  connectionTimeoutMillis: 5_000, // fail fast if can't connect in 5s
  allowExitOnIdle: true,        // let process exit if pool idle
});

// Error handler — REQUIRED. Unhandled 'error' event crashes process.
pool.on('error', (err, client) => {
  console.error('Idle client error:', err.message);
});

// Query helper — auto-release client
export async function query(sql, params) {
  const start = Date.now();
  try {
    const res = await pool.query(sql, params);
    console.debug('Query time:', Date.now() - start, 'ms');
    return res;
  } catch (err) {
    console.error('Query failed:', { sql, err: err.message });
    throw err;
  }
}

// Transaction helper — manual checkout needed
export async function withTransaction(fn) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const result = await fn(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release(); // ALWAYS release — else pool starve
  }
}
```

Usage:

```js
// Simple query
const { rows } = await query('SELECT * FROM users WHERE id = $1', [userId]);

// Transaction
await withTransaction(async (client) => {
  await client.query('UPDATE accounts SET balance = balance - $1 WHERE id = $2', [amount, fromId]);
  await client.query('UPDATE accounts SET balance = balance + $1 WHERE id = $2', [amount, toId]);
});
```

Key traps:

- `pool.on('error')` missing → idle client error crashes process
- `client.release()` missing → pool exhaust, new queries hang until `connectionTimeoutMillis`
- `max` too high → DB hit with too many conn (check `max_connections` in postgres, default 100, leave headroom for admin)
- No `min` → cold start latency on first requests after idle

Shutdown:

```js
process.on('SIGTERM', async () => {
  await pool.end(); // drain pool gracefully
});
```
